import {courseLesson,edit} from './utility-authoring.js';
const L=(...args)=>courseLesson("code",...args);
export const codeUtilsLessons=[
L("types","Convert strings without hiding invalid input",[1, 2, 53],"<p>The utility converters validate input before converting. Unlike permissive builtin conversion, malformed strings produce <code>E_TYPE</code>. <code>type_str()</code> recognizes the six historical types; newer values such as maps report NONE, so use <code>typeof()</code> when you need the actual type code.</p>","text = \"42\";\nplayer:tell(\"TOINT: \", toliteral($code_utils:toint(text)));\nplayer:tell(\"TOOBJ: \", toliteral($code_utils:toobj(\"#55\")));\nplayer:tell(\"INVALID integer: \", toliteral($code_utils:toint(\"brush\")));\nplayer:tell(\"TYPE list: \", toliteral($code_utils:type_str({1, 2})));\nplayer:tell(\"TYPE map limitation: \", toliteral($code_utils:type_str([])));",edit("text = \"42\";","text = \"-7\";","Parse negative seven. The integer output changes while the independently checked values stay the same.")),
L("errors","Convert and name an error value",[3, 4],"<p>An error value can be returned as data. <code>toerr()</code> accepts a known name with or without E_; an unknown name returns the integer 1 rather than raising an exception. <code>error_name()</code> formats the value using its literal representation.</p>","name = \"E_PROPNF\";\nerror = $code_utils:toerr(name);\nplayer:tell(\"ERROR value: \", toliteral(error));\nplayer:tell(\"ERROR name: \", toliteral($code_utils:error_name(error)));\nplayer:tell(\"UNKNOWN error name: \", toliteral($code_utils:toerr(\"NOT_AN_ERROR\")));",edit("E_PROPNF","E_VERBNF","Choose the missing-verb error. Both the value and name change to E_VERBNF.")),
L("references","Parse property and verb references",[13, 14, 31, 59],"<p>Reference parsers return object and member strings; they do not read or call the member. A corified name resolves through object zero. <code>parse_sysobj_map()</code> handles map namespaces when present and returns <code>E_PROPNF</code> when absent.</p>","player:tell(\"PROPERTY reference: \", toliteral($code_utils:parse_propref(\"$list_utils.name\")));\nplayer:tell(\"VERB reference: \", toliteral($code_utils:parse_verbref(\"$list_utils:range\")));\nplayer:tell(\"CORIFIED name: \", toliteral($code_utils:corify_object($list_utils)));\nplayer:tell(\"MISSING namespace: \", toliteral($code_utils:parse_sysobj_map(\"$missing_namespace[tool]\")));",edit("$list_utils.name","$set_utils.name","Parse a property on Set Utils. The parsed object reference changes without reading the name property.")),
L("names","Resolve verb names and aliases",[21, 22, 23, 37],"<p>These searches inspect verbs directly defined on one object, using one-based verb numbers. First/callable searches return zero if absent; last search returns -1. <code>verbname_match()</code> understands aliases and abbreviation markers.</p>","target = $list_utils;\nname = \"range\";\nplayer:tell(\"FIRST number: \", toliteral($code_utils:find_verb_named(target, name)));\nplayer:tell(\"LAST number: \", toliteral($code_utils:find_last_verb_named(target, name)));\nplayer:tell(\"CALLABLE number: \", toliteral($code_utils:find_callable_verb_named(target, name)));\nplayer:tell(\"ABBREVIATION match: \", toliteral($code_utils:verbname_match(\"lo*ok examine\", \"loo\")));",edit("name = \"range\";","name = \"make\";","Find make instead. Its verb index changes; alias matching remains an independent example.")),
L("arguments","Parse a command argument specification",[15, 8, 36],"<p>The shorthand <code>tnt</code> expands to <code>this none this</code>, the usual programmatic specification. Argument specifications control command-line matching, not colon-call arguments. <code>explain_verb_syntax()</code> returns zero for that programmatic form. <code>argstr()</code> repairs historical command-parser spacing cases.</p>","player:tell(\"ARGSPEC: \", toliteral($code_utils:parse_argspec(\"tnt\", \"remaining\")));\nplayer:tell(\"PROGRAMMATIC syntax: \", toliteral($code_utils:explain_verb_syntax(this, \"count\", \"this\", \"none\", \"this\")));\nplayer:tell(\"ARGSTR: \", toliteral($code_utils:argstr(\"look\", {\"at\", \"bench\"}, \"at bench\")));",edit("\"remaining\"","\"extra\"","Change the remaining token. The parsed argument specification stays the same while its unconsumed tail changes.")),
L("prepositions","Normalize command prepositions",[16, 17, 18, 19],"<p>Preposition helpers expose equivalent spellings. <code>short_prep()</code> picks a short form; <code>full_prep()</code> returns the equivalent spelling group; <code>get_prep()</code> consumes a phrase from argument words. Cache refresh temporarily changes a core verb\u2019s argument specification, so this lesson runs on a native server.</p>","player:tell(\"PREPOSITION groups: \", toliteral(length($code_utils:prepositions())));\nplayer:tell(\"SHORT inside: \", toliteral($code_utils:short_prep(\"inside\")));\nplayer:tell(\"FULL in: \", toliteral($code_utils:full_prep(\"in\")));\nplayer:tell(\"CONSUMED phrase: \", toliteral($code_utils:get_prep(\"in\", \"front\", \"of\", \"bench\")));",edit("\"bench\"","\"door\"","Change the trailing object word. The recognized phrase stays in front of and the unused word becomes door."),{"server": {"names": ["prepositions", "short_prep", "full_prep", "get_prep"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object."}}),
L("substitution","Replace code tokens while preserving strings",[32, 38],"<p>Code substitution avoids quoted text and checks token boundaries; it is not a complete syntax-aware refactoring engine. <code>inside_quotes()</code> inspects whether a fragment ends inside a double-quoted string.</p>","source = \"count = count + 1;\";\nplayer:tell(\"SUBSTITUTED: \", toliteral($code_utils:substitute(source, {{\"count\", \"total\"}})));\nplayer:tell(\"QUOTED fragment: \", toliteral($code_utils:inside_quotes(\"player:tell(\\\"hello\")));",edit("\"total\"","\"quantity\"","Choose quantity as the replacement. Both count tokens change to quantity.")),
L("comments","Convert text to source comments and back",[58, 60],"<p>MOO comments commonly use unused string expressions. <code>commentify()</code> quotes and escapes text; <code>uncommentify()</code> validates each comment before evaluating its string. It rejects arbitrary executable code.</p>","text = {\"Inventory notes\", \"Count brushes\"};\ncomments = $code_utils:commentify(text);\nplayer:tell(\"COMMENTS: \", toliteral(comments));\nplayer:tell(\"TEXT again: \", toliteral($code_utils:uncommentify(comments)));",edit("Count brushes","Count saws","Edit the second note. Its quoted source and recovered text change together.")),
L("accessors","Prefer an accessor verb over a raw property",[33, 50],"<p>A callable getter wins over a property with the same name. The setter counterpart looks for <code>set_name()</code> before direct assignment. This allows validation without changing callers. The example uses a temporary plain property and cleans it up.</p>","o = create(#-1);\nadd_property(o, \"quantity\", 3, {player, \"rc\"});\nplayer:tell(\"GET before: \", toliteral($code_utils:verb_or_property(o, \"quantity\")));\nplayer:tell(\"SET result: \", toliteral($code_utils:set_property_value(o, \"quantity\", 7)));\nplayer:tell(\"GET after: \", toliteral($code_utils:verb_or_property(o, \"quantity\")));\nrecycle(o);",edit("\"quantity\", 7","\"quantity\", 9","Set nine instead. The setter result and later getter both show nine.")),
L("documentation","Read and replace leading verb documentation",[11, 12, 42],"<p>Leading string statements provide documentation. These helpers distinguish the full leading documentation from usage lines. Updating documentation changes source; use only a private scratch verb and inspect its behavior afterward.</p>","o = create(#-1);\nadd_verb(o, {player, \"rxd\", \"example\"}, {\"this\", \"none\", \"this\"});\nset_verb_code(o, \"example\", {\"return 3;\"});\nplayer:tell(\"SET documentation: \", toliteral($code_utils:set_verb_documentation(o, \"example\", \"Usage: example()\")));\nplayer:tell(\"DOCUMENTATION: \", toliteral($code_utils:verb_documentation(o, \"example\")));\nplayer:tell(\"USAGE: \", toliteral($code_utils:verb_usage(o, \"example\")));\nplayer:tell(\"BEHAVIOR unchanged: \", toliteral(o:example()));\nrecycle(o);",edit("return 3;","return 4;","Change the scratch verb\u2019s return value to four. Its documentation stays the same and its behavior changes."),{"server": {"names": ["set_verb_documentation", "verb_documentation", "verb_usage"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object.", "wizard": true}}),
L("inspection","Print an object and member inspection",[5, 6, 7],"<p>These helpers print multi-line reports through the player\u2019s notification interface. <code>show_object()</code> can limit its report to selected member categories; property and verb reports include permissions. Printed reports are distinct from their returned value.</p>","target = $list_utils;\nplayer:tell(\"OBJECT report:\");\n$code_utils:show_object(target, {});\nplayer:tell(\"PROPERTY report:\");\n$code_utils:show_property(target, \"name\");\nplayer:tell(\"VERB report:\");\n$code_utils:show_verbdef(target, \"range\");",edit("\"range\"","\"make\"","Inspect make in the final report. The object and name-property reports stay the same.")),
L("source-search","Search a bounded set of verb definitions",[24],"<p>Always give a target object while learning; omitting it can scan the whole database. The containing aliases use literal text, matching aliases use regular expressions, and the lines variants print all matching lines instead of only the first.</p>","target = $set_utils;\nplayer:tell(\"LITERAL first matching lines:\");\n$code_utils:find_verbs_containing(\"return\", target);\nplayer:tell(\"REGEX all matching lines:\");\n$code_utils:find_verb_lines_matching(\"^return\", target);",edit("\"return\", target","\"E_TYPE\", target","Search for E_TYPE in the literal search. Fewer definitions match; the independent regex search stays the same."),{"server": {"names": ["find_verbs_containing"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object."}}),
L("stack","Read execution context and stack frames",[9, 10, 43, 44, 52],"<p>Permission identity, receiver and defining object are different concepts. These wrappers describe the calling frame. A top-level Eval task may have fewer frames than a normal verb call. The debug flag affects whether errors become tracebacks.</p>","player:tell(\"PERMISSIONS: \", toliteral($code_utils:verb_perms()));\nplayer:tell(\"DEFINITION location: \", toliteral($code_utils:verb_location()));\nplayer:tell(\"CALLING frame: \", toliteral($code_utils:verb_frame()));\nplayer:tell(\"ALL frame count: \", toliteral(length($code_utils:verb_all_frames())));\nplayer:tell(\"DEBUG enabled: \", toliteral($code_utils:dflag_on()));",edit("verb_perms()","verb_permissions()","Use the longer alias. It reports the same permission identity."),{"server": {"names": ["verb_perms", "verb_location", "verb_frame", "verb_all_frames", "dflag_on"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object."}}),
L("tasks","Inspect queued task ownership",[34, 35, 51],"<p>Queued tasks exclude the currently running task. <code>task_owner()</code> returns an error for an absent queued task; <code>owns_task()</code> returns an association record or an empty list. <code>task_valid()</code> also checks the running task and permission behavior, so it is not just membership in queued_tasks.</p>","id = -1;\nplayer:tell(\"TASK valid: \", toliteral($code_utils:task_valid(id)));\nplayer:tell(\"TASK owner: \", toliteral($code_utils:task_owner(id)));\nplayer:tell(\"OWNS task: \", toliteral($code_utils:owns_task(id, player)));",edit("id = -1;","id = -2;","Try another impossible task identifier. Both are absent from the disposable server queue."),{"server": {"names": ["task_valid", "task_owner", "owns_task"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object."}}),
L("move-members","Move a property and verb between scratch objects",[45, 46],"<p>Moving removes the member from its old object. The caller needs control of both objects, ownership of the member, and programmer permissions. Save work and use private scratch objects; names and permissions move with the source unless renamed.</p>","a = create(#-1);\nb = create(#-1);\nadd_property(a, \"quantity\", 3, {player, \"rc\"});\nadd_verb(a, {player, \"rxd\", \"count\"}, {\"this\", \"none\", \"this\"});\nset_verb_code(a, \"count\", {\"return 3;\"});\n$code_utils:move_property(a, \"quantity\", b);\n$code_utils:move_verb(a, \"count\", b, \"total\");\nplayer:tell(\"MOVED property: \", toliteral(b.quantity));\nplayer:tell(\"MOVED verb: \", toliteral(b:total()));\nrecycle(a);\nrecycle(b);",edit("return 3;","return 5;","Change the scratch verb to return five before moving it. The moved property stays three and the moved verb returns five."),{"server": {"names": ["move_property", "move_verb"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object.", "wizard": true}}),
L("help","Search the player\u2019s help databases",[29, 30],"<p>The help database list depends on the player, ancestors and location. Search can return a database/topic pair, an ambiguity result or an empty list. An empty database list is a useful deterministic no-match case.</p>","player:tell(\"HELP database count: \", toliteral(length($code_utils:help_db_list(player))));\nplayer:tell(\"EMPTY search: \", toliteral($code_utils:help_db_search(\"brush\", {})));",edit("\"brush\"","\"saw\"","Search for saw in the empty list. No help database is consulted, so the result remains empty.")),
L("dump","Generate portable object reconstruction text",[54, 55, 56],"<p>Dump helpers return command text; they do not execute it. The preamble creates an object, property output describes data, and verb output includes programming commands. Print one line at a time and review ownership and references before importing elsewhere.</p>","o = create($thing);\no.name = \"Practice\";\nadd_property(o, \"quantity\", 3, {player, \"rc\"});\nplayer:tell(\"PREAMBLE: \", $code_utils:dump_preamble(o));\nplayer:tell(\"PROPERTIES:\");\nfor line in ($code_utils:dump_properties(o, 1, \"scratch\"))\n  player:tell(line);\nendfor\nplayer:tell(\"VERBS:\");\nfor line in ($code_utils:dump_verbs(o, 1, \"scratch\"))\n  player:tell(line);\nendfor\nrecycle(o);",edit("\"quantity\", 3","\"quantity\", 5","Change the property\u2019s initial value to five. The generated property command changes; it still does not execute automatically."),{"server": {"names": ["dump_preamble", "dump_properties", "dump_verbs"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object."}}),
L("debug-eval","Evaluate with historical non-debug behavior",[0],"<p>Unlike ordinary debug evaluation, <code>eval_d()</code> executes with the debug flag unset. It temporarily rewrites its auxiliary core verb and returns a compiled flag plus result. This is a native-server exercise because it changes core source during execution; do not use it to bypass validation of untrusted code.</p>","player:tell(\"EVAL D result: \", toliteral($code_utils:eval_d(\"return 1 + 2;\")));",edit("1 + 2","2 + 3","Change the expression. A successful compilation returns a result of five."),{"server": {"names": ["eval_d"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object.", "wizard": true}}),
L("formatted-stack","Format a supplied stack for people",[48, 49],"<p>Stack formatting returns one line per row; display_callers sends those lines through the player\u2019s paging interface. Supply a captured stack to report the same frames twice. Native List Utils slicing and a player with formatting verbs are required.</p>","frames = {};\nplayer:tell(\"FORMATTED stack:\");\nfor line in ($code_utils:callers_text(frames))\n  player:tell(line);\nendfor\nplayer:tell(\"DISPLAY helper:\");\n$code_utils:display_callers(frames);",edit("frames = {};","frames = callers();","Use the current stack instead of an empty one. The report gains rows for available callers."),{"server": {"names": ["callers_text", "display_callers"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object."}}),
L("who-report","Report connected and disconnected players",[39],"<p>The who report combines connection duration, idle duration and location; disconnected players use their stored timestamps. Ordering and column widths depend on the live server and caller. An empty input returns zero without a report.</p>","player:tell(\"EMPTY WHO report: \", toliteral($code_utils:show_who_listing({})));",edit("show_who_listing({})","show_who_listing({}, {})","Supply an explicitly empty disconnected list as well. There are still no rows."),{"server": {"names": ["show_who_listing"], "prerequisites": "A disposable ToastStunt server with the pinned ToastCore, a programmer account and a private scratch object."}}),
L("reference-report","Build a reference inspection report",[],"<p>Parse a verb reference, convert the object string, then inspect its callable definition. Keep these stages separate so invalid input can be handled before trying to call or modify anything.</p>","reference = \"$list_utils:range\";\nparts = $code_utils:parse_verbref(reference);\nplayer:tell(\"PARSED: \", toliteral(parts));\ntarget = $code_utils:toobj(parts[1]);\nplayer:tell(\"CALLABLE: \", toliteral($object_utils:has_callable_verb(target, parts[2])));",edit("$list_utils:range","$set_utils:union","Inspect Set Utils union instead. Both the parsed reference and its defining object change.")),
];
export const codeExclusions={"20": "Internal preposition cache rebuild, reached through public preposition helpers.", "25": "Internal worker for public source search.", "26": "Internal literal-source search implementation.", "27": "Internal regular-expression source search implementation.", "28": "Internal parser for audit commands, not a standalone code utility interface.", "40": "Internal all-lines regex worker used by public source search.", "41": "Internal all-lines literal worker used by public source search.", "47": "Mutable auxiliary implementation of eval_d(); never call directly.", "57": "Internal source-search reporting worker."};
